CREATE TABLE password_device (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,name VARCHAR(256) NOT NULL,device_type VARCHAR(64) NOT NULL,trust_state VARCHAR(24) NOT NULL DEFAULT 'TRUSTED',last_sync_at TIMESTAMPTZ,last_unlock_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(trust_state IN ('TRUSTED','REVOKED')),UNIQUE(owner_id,name)); CREATE INDEX idx_password_device_owner ON password_device(owner_id,created_at DESC);
